contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address receiver, uint256 amount) public {
        require(receiver != address(0));
        require(amount > 0);

        // read-only call: total shares claimable by this contract right now
        uint256 before = c.unclaimedShares(address(this));

        bool reverted;
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: claim either reverts, or the claimed amount was
        // covered by the claimer's unclaimed shares (which include any
        // pending round credit the view also accounts for).
        assert(reverted || amount <= before);
    }

    receive() external payable {}
}

