contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint256 amount) public payable {
        // rule: claim with zero amount must revert for any receiver
        bool revertedZeroAmount;
        try c.claim(receiver, 0) { revertedZeroAmount = false; }
        catch { revertedZeroAmount = true; }

        // rule: claim to the zero-address receiver must revert for any nonzero amount
        bool revertedZeroReceiver;
        if (receiver == address(0) && amount == 0) {
            revertedZeroReceiver = revertedZeroAmount;
        } else if (receiver == address(0)) {
            try c.claim(receiver, amount) { revertedZeroReceiver = false; }
            catch { revertedZeroReceiver = true; }
        } else {
            try c.claim(address(0), 1) { revertedZeroReceiver = false; }
            catch { revertedZeroReceiver = true; }
        }

        assert(revertedZeroAmount && revertedZeroReceiver);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address receiver, uint256 extra) public payable {
        require(receiver != address(0));

        // available unclaimed shares of the claimer (this contract), read via public view
        uint256 available = c.unclaimedShares(address(this));

        // claiming strictly more than the unclaimed balance must revert
        bool reverted;
        try c.claim(receiver, available + extra + 1) { reverted = false; }
        catch { reverted = true; }

        // no shares may have been moved out of the claimer's unclaimed balance
        uint256 availableAfter = c.unclaimedShares(address(this));

        assert(reverted && availableAfter == available);
    }

    receive() external payable {}
}

